// Turns the pasted lines into table rows: clean the phone, merge the name, drop duplicates and the stop list.
const s = $('Settings').first().json;
const form = $('New batch form').first().json;
const recent = $('Read recent notices').all().map((item) => item.json).filter((row) => row.id !== undefined);
const country = String(s.default_country_code || '55').replace(/\D/g, '');

// A refused submission saves nothing and sends nothing. The form shows the reason.
const refuse = (reason) => [{ json: { refused: true, reason } }];
if (!/^\+[1-9]\d{7,14}$/.test(String(s.owner_phone || '').replace(/[\s().-]/g, ''))) {
  return refuse('Settings: set owner_phone to your own WhatsApp number with the country code, for example +5511977770001. The summaries are sent there.');
}
const template = String(form['Message'] || '').trim() || String(s.default_message || '').trim();
if (!template) return refuse('Write a message in the form: it is required.');
if (template.length > Number(s.max_message_length)) {
  return refuse('The message has ' + template.length + ' characters, the limit is ' + s.max_message_length + '.');
}

// Phone numbers: E.164 only where it is unambiguous, otherwise the row is marked invalid_phone.
function international(digits) {
  if (!/^[1-9]\d{7,14}$/.test(digits)) return { error: 'Not a valid international number' };
  if (digits.startsWith('55') && !(digits.length === 13 && digits[4] === '9')) {
    return { error: 'A Brazilian mobile number has the country code 55, the area code, then 9 and 8 more digits' };
  }
  return { phone: '+' + digits };
}
function toE164(raw) {
  const cleaned = String(raw).trim().replace(/[\s().-]/g, '');
  if (!/^\+?\d+$/.test(cleaned)) return { error: 'Not a phone number: use digits, with the area code' };
  if (cleaned.startsWith('+')) return international(cleaned.slice(1));
  if (cleaned.startsWith('00')) return international(cleaned.slice(2));
  let digits = cleaned;
  if (country === '55') {
    digits = digits.replace(/^0(?=\d{10,11}$)/, '');
    if (/^55\d{11}$/.test(digits)) return international(digits);
    if (/^[1-9][1-9]9\d{8}$/.test(digits)) return international('55' + digits);
    if (/^(55)?[1-9][1-9]\d{8}$/.test(digits)) return { error: 'Looks like a number without the ninth digit: add the 9 after the area code' };
    return { error: 'Use the area code and the 9 digit mobile number, or start with + and the country code' };
  }
  if (digits.startsWith(country)) return international(digits);
  return { error: 'Start with + and the country code' };
}

const mergeName = (name) =>
  template.replace(/([ \t]*)\{name\}/gi, (_, space) => (name ? space + name : '')).trim();

const stopList = new Set(
  String(s.stop_list || '').split(/[,;\n]/).map((entry) => entry.trim()).filter(Boolean).map((entry) => toE164(entry).phone).filter(Boolean),
);

const stamp = new Date().toISOString().slice(0, 16).replace(/[-:]/g, '').replace('T', '-');
const batchId = stamp + '-' + Math.random().toString(36).slice(2, 5);
const label = String(form['Batch label'] || '').trim().slice(0, 60);

const alreadyNotified = new Set(
  recent
    .filter((row) => ['queued', 'sent', 'delivered', 'read', 'no_receipt'].includes(row.status))
    .filter((row) => Date.parse(row.createdAt) >= Date.now() - Number(s.dedupe_days) * 86400000)
    .map((row) => row.phone + '|' + row.message),
);

const lines = String(form['Recipients'] || '').split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
if (!lines.length) return refuse('The list of recipients is empty.');
if (lines.length > Number(s.max_recipients_per_submission)) {
  return refuse('The list has ' + lines.length + ' lines, the limit for one submission is ' + s.max_recipients_per_submission + '.');
}

const seen = new Set();
const rows = [];
lines.forEach((line, index) => {
  if (index === 0 && /^["']?name["']?\s*[\t,;]\s*["']?(phone|number)/i.test(line)) return;
  // A paste from a spreadsheet is separated by a tab, otherwise a semicolon, otherwise a comma.
  const separator = line.includes('\t') ? '\t' : line.includes(';') ? ';' : ',';
  const cut = line.lastIndexOf(separator);
  const name = (cut === -1 ? '' : line.slice(0, cut)).trim().replace(/^"|"$/g, '').trim().slice(0, 90);
  const rawPhone = (cut === -1 ? line : line.slice(cut + 1)).trim().replace(/^"|"$/g, '');
  const row = {
    name, phone: rawPhone, message: '', status: 'queued', message_id: '', error: '', batch_id: batchId, label,
    sent_at: '', delivered_at: '', read_at: '', reported_at: '',
  };
  const parsed = toE164(rawPhone);
  if (parsed.error) {
    rows.push({ ...row, status: 'invalid_phone', error: parsed.error });
    return;
  }
  row.phone = parsed.phone;
  row.message = mergeName(name);
  if (stopList.has(row.phone)) {
    row.status = 'opted_out';
    row.error = 'This number is on your stop list';
  } else if (seen.has(row.phone)) {
    row.status = 'duplicate';
    row.error = 'The same number appears earlier in this batch';
  } else if (alreadyNotified.has(row.phone + '|' + row.message)) {
    row.status = 'duplicate';
    row.error = 'This number already got, or is about to get, this text in the last ' + s.dedupe_days + ' days';
  }
  seen.add(row.phone);
  rows.push(row);
});
if (!rows.length) return refuse('No line to send was found in the list.');

// Daily cap across batches: rows that count as a message in the last 24 hours, plus this batch.
const dayAgo = Date.now() - 24 * 3600000;
const today = recent.filter((row) => ['queued', 'sent', 'delivered', 'read', 'failed', 'no_receipt'].includes(row.status) && Date.parse(row.createdAt) >= dayAgo).length;
const adding = rows.filter((row) => row.status === 'queued').length;
if (today + adding > Number(s.daily_cap)) {
  return refuse('This batch adds ' + adding + ' messages to the ' + today + ' of the last 24 hours, and the daily cap is ' + s.daily_cap + '.');
}
return rows.map((json) => ({ json }));

// Compares the queued rows with the quota left in this billing cycle. Only what fits is sent.
const settings = $('Settings').first().json;
const quota = $('Get message quota').first().json;
if (quota.error) {
  throw new Error('Could not read your quota, so nothing was sent: ' + quota.error + '. The lines are saved as queued. They go out with the next batch you send, unless they are older than ' + settings.queued_max_age_hours + ' hours by then: such a line is marked as too old and not sent.');
}
const recent = $('Read recent notices').all().map((item) => item.json).filter((row) => row.id !== undefined);
const inserted = $input.all().map((item) => item.json).filter((row) => row.id !== undefined);
// Rows left queued by an earlier run come first, then this batch, always in the order they were saved.
const queued = [...recent, ...inserted].filter((row) => row.status === 'queued');
const maxAge = Number(settings.queued_max_age_hours) * 3600000;
const left = Math.max(0, Number(quota.remaining) || 0);
let room = Math.max(0, left - 1); // one message stays free for your summary
const resets = String(quota.resets_at || '').slice(0, 10);
return queued.map((row) => {
  const stale = Date.now() - Date.parse(row.createdAt) > maxAge;
  let action = 'send';
  let status = 'queued';
  let reason = '';
  if (stale) {
    action = 'skip_stale';
    status = 'skipped_stale';
    reason = 'Not sent: this line waited more than ' + settings.queued_max_age_hours + ' hours in the queue. Paste it into the form again if the notice is still true.';
  } else if (room > 0) {
    room -= 1;
  } else {
    action = 'skip_quota';
    status = 'skipped_quota';
    reason = 'Not sent: ' + left + ' messages were left in this billing cycle (it resets ' + resets + '). Paste the line into the form again when there is room.';
  }
  return {
    json: { row_id: row.id, name: row.name, phone: row.phone, message: row.message, batch_id: row.batch_id, action, status_after: status, reason },
    pairedItem: { item: 0 },
  };
});

// Applies the delivery news (or the hourly check) to the rows. A row only moves forward: sent, delivered, read.
const settings = $('Settings').first().json;
const rows = $('Read open notices').all().map((item) => item.json).filter((row) => row.id !== undefined);
const rank = { sent: 1, no_receipt: 1, delivered: 2, read: 3 };
const byMessage = new Map(rows.filter((row) => row.message_id).map((row) => [row.message_id, row]));
const changes = new Map();
const change = (row) => {
  if (!changes.has(row.id)) {
    changes.set(row.id, { row_id: row.id, previous_status: row.status, status: row.status, delivered_at: row.delivered_at || '', read_at: row.read_at || '', error: row.error || '', dirty: false });
  }
  return changes.get(row.id);
};

if ($('New delivery and failure events').isExecuted) {
  // A receipt for our message carries the message id in data.id (its direction says inbound: the recipient's phone sent it).
  const events = $('New delivery and failure events').all().map((item) => item.json)
    .sort((a, b) => String(a.created_at).localeCompare(String(b.created_at)));
  for (const event of events) {
    const row = byMessage.get(event.data?.id);
    if (!row) continue; // not a notice of this table
    const next = change(row);
    const at = event.data.at || event.created_at;
    if (event.type === 'message.read' && rank[next.status] < 3) {
      Object.assign(next, { status: 'read', read_at: at, error: '', dirty: true });
    } else if (event.type === 'message.delivered' && rank[next.status] < 2) {
      Object.assign(next, { status: 'delivered', delivered_at: at, error: '', dirty: true });
    } else if (event.type === 'message.delivered' && !next.delivered_at) {
      Object.assign(next, { delivered_at: at, dirty: true }); // the news came late: the row stays read, it only learns when it was delivered
    } else if (event.type === 'message.send.failed' && rank[next.status] < 2) {
      const failure = event.data.error || {};
      Object.assign(next, { status: 'failed', error: [failure.code, failure.message].filter(Boolean).join(': ') || 'WhatsApp could not deliver the message', dirty: true });
    }
  }
} else {
  // The hourly check: a row that is still "sent" with no news for report_after_hours is closed as no_receipt.
  const limit = Date.now() - Number(settings.report_after_hours) * 3600000;
  for (const row of rows) {
    if (row.status === 'sent' && Date.parse(row.updatedAt) <= limit) {
      Object.assign(change(row), { status: 'no_receipt', error: 'No delivery or read news from WhatsApp after ' + settings.report_after_hours + ' hours', dirty: true });
    }
  }
}

const out = [...changes.values()].filter((item) => item.dirty).map(({ dirty, ...json }) => ({ json }));
// Something must flow on even when nothing changed, because the summary check after the save always runs.
// This placeholder matches no row (the id 0 does not exist), so saving it changes nothing.
return out.length ? out : [{ json: { row_id: 0, previous_status: '', status: '', delivered_at: '', read_at: '', error: '' } }];

// One summary per batch that is finished, or older than report_after_hours. Rows of a batch share batch_id.
const settings = $('Settings').first().json;
const quota = $('Get message quota').first().json;
const rows = $('Read unreported rows').all().map((item) => item.json).filter((row) => row.id !== undefined);
const owner = String(settings.owner_phone || '').replace(/[\s().-]/g, '');
if (rows.length && !/^\+[1-9]\d{7,14}$/.test(owner)) {
  throw new Error('Settings: set owner_phone to your own WhatsApp number with the country code, for example +5511977770001. The summaries are sent there.');
}
const FINAL = new Set(['delivered', 'read', 'failed', 'invalid_phone', 'duplicate', 'opted_out', 'skipped_quota', 'skipped_stale', 'held', 'no_receipt']);
const plain = (text) => String(text || '').replace(/[.\s]+$/, '');

const batches = new Map();
for (const row of rows) {
  if (!batches.has(row.batch_id)) batches.set(row.batch_id, []);
  batches.get(row.batch_id).push(row);
}

const out = [];
for (const [batchId, list] of batches) {
  const everyRowIsFinal = list.every((row) => FINAL.has(row.status));
  const startedAt = Math.max(...list.map((row) => Date.parse(row.createdAt)));
  const tooOld = Date.now() - startedAt >= Number(settings.report_after_hours) * 3600000;
  if (!everyRowIsFinal && !tooOld) continue;

  const count = (status) => list.filter((row) => row.status === status).length;
  const read = count('read');
  const delivered = count('delivered') + read;
  const waiting = list.filter((row) => !FINAL.has(row.status)).length;
  const failed = list.filter((row) => row.status === 'failed');
  const held = list.filter((row) => row.status === 'held');
  const parts = [
    'delivered ' + delivered + ' (read so far ' + read + ')',
    failed.length && 'failed ' + failed.length,
    held.length && 'held ' + held.length,
    count('invalid_phone') && 'invalid number ' + count('invalid_phone'),
    count('duplicate') && 'duplicate ' + count('duplicate'),
    count('opted_out') && 'on your stop list ' + count('opted_out'),
    count('skipped_quota') && 'not sent, quota short ' + count('skipped_quota'),
    count('skipped_stale') && 'not sent, waited too long ' + count('skipped_stale'),
    count('no_receipt') && 'no delivery news yet ' + count('no_receipt'),
    waiting && 'still waiting ' + waiting,
  ].filter(Boolean);

  const label = list[0].label ? '"' + list[0].label + '" ' : '';
  const lines = [
    'Notices batch ' + label + '(' + batchId + ') ' + (everyRowIsFinal ? 'is done' : 'is closed after ' + settings.report_after_hours + ' hours') + ': ' + (list.length === 1 ? '1 person' : list.length + ' people') + '.',
    parts.join(', ') + '.',
  ];
  if (failed.length) {
    const shown = failed.slice(0, 10).map((row) => row.name + ' (' + row.phone + '): ' + plain(row.error));
    lines.push('Failed: ' + shown.join('; ') + (failed.length > 10 ? '; and ' + (failed.length - 10) + ' more' : '') + '.');
  }
  if (held.length) {
    const reasons = [...new Set(held.map((row) => plain(row.error).replace(/^Held: /, '')))];
    lines.push('Held, not sent: ' + reasons.join(' / ') + '.');
  }
  if (!quota.error) {
    lines.push('Messages left in this cycle: ' + quota.remaining + ' of ' + quota.quota + '.');
  }
  lines.push('This is a snapshot: the notices table keeps updating as delivery and read news arrive.');
  if (failed.length || held.length || count('skipped_quota') || count('skipped_stale')) {
    lines.push('To send those lines again, paste them into the form again. People who already got the text are skipped.');
  }
  out.push({ json: { batch_id: batchId, to: owner, summary: lines.join('\n') }, pairedItem: { item: 0 } });
}
return out;
